--
-- Name: v_tickets_for_producto; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_tickets_for_producto AS
 SELECT p.id,
    p.name,
    count(t.id) AS total_tickets
   FROM ((public.product p
     JOIN public.components c ON ((p.id = c.product_id)))
     JOIN public.ticket_request t ON ((c.id = t.components_id)))
  GROUP BY p.id, p.name;


ALTER VIEW public.v_tickets_for_producto OWNER TO postgres;

--
-- Name: vw_task_request_details; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_task_request_details AS
 SELECT tk.id,
    tk.ticket_id,
    tk.created_by,
    tk.topic,
    tk.description,
    tk.created_at,
    tk.expired_in,
    tk.closed_in,
    pri.name AS priority_name,
    st.name AS status_name,
    dpt.name AS assigned_departament_name,
    usr.name AS assigned_user_name
   FROM ((((public.task_request tk
     LEFT JOIN public.priority pri ON ((tk.priority_id = pri.id)))
     LEFT JOIN public.status st ON ((tk.status_id = st.id)))
     LEFT JOIN public.departament dpt ON ((tk.assigned_departament = dpt.id)))
     LEFT JOIN public.users usr ON (((tk.assigned_user)::text = (usr.id)::text)));


ALTER VIEW public.vw_task_request_details OWNER TO postgres;

--
-- Name: vw_ticket_request_details; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_ticket_request_details AS
 SELECT tr.id,
    tr.ticket_bcv,
    tr.topic,
    tr.description,
    tr.created_by,
    tr.created_at,
    tr.expired_in,
    pri.name AS priority,
    pr.name AS product,
    c_aff.name AS affected_customer,
    s.name AS sla,
    cmp.name AS component,
    sub.name AS subcomponent,
    cnt.name AS contact,
    tp.name AS type_request,
    env.name AS environment_id,
    last_break.current_status
   FROM ((((((((((public.ticket_request tr
     LEFT JOIN ( SELECT DISTINCT ON (tb.ticket_id) tb.ticket_id,
            st.name AS current_status,
            tb.created_at
           FROM (public.ticket_break tb
             LEFT JOIN public.status st ON ((tb.status_paused = st.id)))
          ORDER BY tb.ticket_id, tb.created_at DESC, tb.id DESC) last_break ON (((tr.id)::text = (last_break.ticket_id)::text)))
     LEFT JOIN public.type_request tp ON ((tr.type_request = tp.id)))
     LEFT JOIN public.environment env ON ((tr.environment_id = env.id)))
     LEFT JOIN public.priority pri ON ((tr.priority = pri.id)))
     LEFT JOIN public.product pr ON ((tr.product_id = pr.id)))
     LEFT JOIN public.customers c_aff ON (((tr.affected_customer_id)::text = (c_aff.rif)::text)))
     LEFT JOIN public.sla s ON ((tr.sla_id = s.id)))
     LEFT JOIN public.components cmp ON ((tr.components_id = cmp.id)))
     LEFT JOIN public.subcomponents sub ON ((tr.subcomponents_id = sub.id)))
     LEFT JOIN public.contact cnt ON ((tr.contact_id = cnt.id)));


ALTER VIEW public.vw_ticket_request_details OWNER TO postgres;

